def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in ``[low, high]`` with equally many even and odd
    digits that are divisible by ``k``.

    Leading zeroes are not considered digits, so zero itself is not included
    (the documented input range is positive).
    """

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0

        digits = tuple(map(int, str(bound)))
        length = len(digits)

        @lru_cache(maxsize=None)
        def visit(position: int, remainder: int, balance: int,
                  started: bool, tight: bool) -> int:
            if position == length:
                return int(started and remainder == 0 and balance == 0)

            limit = digits[position] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == limit
                if not started and digit == 0:
                    total += visit(position + 1, 0, balance, False, next_tight)
                    continue

                next_balance = balance + (1 if digit % 2 == 0 else -1)
                # A remaining suffix cannot bridge a balance whose magnitude
                # already exceeds the number of remaining digits.
                remaining = length - position - 1
                if abs(next_balance) <= remaining:
                    next_remainder = (remainder * 10 + digit) % k
                    total += visit(position + 1, next_remainder, next_balance,
                                   True, next_tight)
            return total

        return visit(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

